<section class="tt-domain" aria-labelledby="tt-domain-title"><div><p class="tt-kicker">YOUR NEXT ADDRESS</p><h2 id="tt-domain-title">Find your domain.</h2><p class="tt-sub">Search for a name for your business or next project.</p></div><form action="{{ url('/client/domain-search') }}" method="GET"><label for="tt-domain-query">Enter a domain name</label><div class="tt-search"><input id="tt-domain-query" name="domain" type="text" required maxlength="253" placeholder="yourbusiness.co.uk" autocomplete="off" spellcheck="false"><button class="tt-button" type="submit">SEARCH DOMAIN</button></div><p class="tt-hint">Availability and prices are shown in the domain search results.</p></form></section>
